row('Lot B book on-hand was 34 units after all three requested cartons shipped.',['06-shipping-tickets-scan.pdf#[T04]','02-opening-and-journal.md#[J03]'],'refuted','refutation','Only two cartons shipped; canceled remainder never left; on-hand40.'),
r('Lot B available stock was 32 units.',['01-stock-rules.md#[R03]','02-opening-and-journal.md#[J03]']),
